<script setup>
import {reactive,watch} from 'vue'
import {onShow,onHide,onUnload} from '@dcloudio/uni-app'
import {ownerSession,clearOwnerSession} from '../../services/owner-session.js'
import {createPointsApi,createCheckinRecovery,POINT_STATES} from '../../services/points-ledger.js'
import {POINT_TASKS} from '../../services/point-task-policies.js'
import {initialDiagnosisState,createAsyncDiagnosisFlow} from '../../services/async-diagnosis.js'
import {imageRequestKey} from '../../services/private-images.js'
import {displayTime} from '../../services/reservations.js'
const api=createPointsApi(),state=reactive(initialDiagnosisState()),token=()=>ownerSession.accessToken
const flow=createAsyncDiagnosisFlow({state,token,scope:()=> 'point-checkin',allowed:()=>ownerSession.actorId>0,recovery:createCheckinRecovery({actor:()=>ownerSession.actorId}),newKey:imageRequestKey,
 load:async(t,p)=>{const [overview,entries]=await Promise.all([api.overview(t),api.flow(t,p)]);return {overview,entries}},write:(t,a,id,b,k)=>api.checkin(t,b,k),
 confirm:action=>new Promise(resolve=>uni.showModal({title:action==='discard-local'?'核对并清理本机签到请求':'确认今日签到',content:action==='discard-local'?'请核对刚读取的签到状态和到账流水。只清理本机恢复记录，不删除服务器记录，不重新签到。':`按服务器北京时间 ${state.data?.overview.day} 登记签到，分值以本次确认的有效规则为准。原日期、规则和请求编号会保存在本机，用于断线恢复；登记不代表已经到账。`,success:r=>resolve(r.confirm),fail:()=>resolve(false)}))})
let visible=false
function sign(){const o=state.data?.overview,t=o?.tasks[0];if(t?.state!=='READY'||!t.policy||state.busy||state.retry)return;flow.save('checkin',0,{day:o.day,policy_id:t.policy.id,policy_revision:t.policy.revision})}
function login(){clearOwnerSession();uni.navigateTo({url:'/pages/owner/index'})}
watch(()=>ownerSession.accessToken,()=>{flow.reset();if(visible&&token())flow.load()},{flush:'sync'})
onShow(()=>{visible=true;if(token())flow.load()});onHide(()=>{visible=false;flow.reset()});onUnload(()=>{visible=false;flow.reset()})
</script>
<template><view class="reservation-page"><text class="reservation-title">我的积分</text><button @tap="uni.navigateTo({url:'/pages/points/exchange'})">积分兑换券与成功记录</button><button v-if="!token()||!ownerSession.actorId" @tap="login">登录车主账号</button><text v-if="state.busy">正在核对本人积分…</text><text v-if="state.message" role="status">{{state.message}}</text><button v-if="['unauthorized','forbidden'].includes(state.kind)" @tap="login">重新登录</button><button v-if="state.retry" :disabled="state.busy" @tap="flow.retry">重试原日期签到请求</button><button v-if="state.kind==='storage'" :disabled="state.busy" @tap="flow.discardLocal">核对服务器并清理本机请求</button><button v-if="token()" :disabled="state.busy" @tap="flow.load(state.page)">刷新任务与积分明细</button><template v-if="state.data"><view class="reservation-panel"><text class="reservation-heading">已核验积分 {{state.data.overview.balance}}</text><text>仅包含有来源的已到账任务积分，并扣除成功兑换的积分。</text><text v-if="state.data.overview.legacy_state==='REVIEW_REQUIRED'">历史积分来源待核对，未计入此余额。</text><text v-if="!state.data.overview.earning_available">当前积分任务暂不可领取，请稍后刷新或重新核对账号。</text><text>北京时间 {{state.data.overview.day}}</text></view><view v-for="(t,i) in state.data.overview.tasks" :key="t.task_type" class="reservation-panel"><text class="reservation-heading">{{POINT_TASKS[t.task_type]}}</text><text>{{POINT_STATES[t.state]}} · {{t.frequency==='DAILY'?'北京自然日一次':'每账号一次，换规则不重发'}}</text><template v-if="t.policy"><text>{{['PENDING','CREDITED'].includes(t.state)?'登记时规则':'当前规则'}} {{t.policy.points}} 积分 · {{t.policy.source_note}}</text><text>{{displayTime(t.policy.valid_from)}} 至 {{displayTime(t.policy.valid_to)}}</text></template><text v-else>尚无有效来源规则。</text><text v-if="t.state==='CREDITED'">本次到账 {{t.points_awarded}} 积分 · {{displayTime(t.credited_at)}}</text><text v-if="t.state==='PENDING'">任务已登记，等待到账。请稍后刷新。</text><button v-if="i===0&&t.state==='READY'" :disabled="state.busy||state.retry||state.kind==='storage'" @tap="sign">确认今日签到</button><button v-if="i===1&&t.state==='READY'" @tap="uni.switchTab({url:'/pages/archive/index'})">完善并确认本人档案</button><button v-if="i===2&&t.state==='READY'" @tap="uni.switchTab({url:'/pages/ai/index'})">前往 AI 管家</button></view><view class="reservation-panel"><text class="reservation-heading">积分明细</text><text v-if="!state.data.entries.items.length">暂无已核验积分记录。</text><view v-for="r in state.data.entries.items" :key="r.id"><text>{{r.delta<0?'兑换券':POINT_TASKS[r.task_type]}} {{r.delta>0?'+':''}}{{r.delta}} · 余额 {{r.balance_after}}</text><text>{{displayTime(r.created_at)}} · {{r.delta<0?'兑换目录':'来源规则'}} #{{r.delta<0?r.catalog_id:r.policy_id}} / 版本 {{r.delta<0?r.catalog_revision:r.policy_revision}}</text></view><button v-if="state.page>1" :disabled="state.busy" @tap="flow.load(state.page-1)">上一页</button><button v-if="state.page*20<state.data.entries.total" :disabled="state.busy" @tap="flow.load(state.page+1)">下一页</button></view></template></view></template>
